import{_ as a,o as s,c as n,a2 as r}from"./chunks/framework.CiQ1TEvV.js";const h=JSON.parse('{"title":"Hybrid Retrieval","description":"","frontmatter":{},"headers":[],"relativePath":"features/hybrid-retrieval.md","filePath":"features/hybrid-retrieval.md","lastUpdated":1785115728000}'),i={name:"features/hybrid-retrieval.md"};function t(l,e,o,c,d,p){return s(),n("div",null,[...e[0]||(e[0]=[r(`<h1 id="hybrid-retrieval" tabindex="-1">Hybrid Retrieval <a class="header-anchor" href="#hybrid-retrieval" aria-label="Permalink to &quot;Hybrid Retrieval&quot;">​</a></h1><p>Pure vector retrieval is good at semantic similarity, but it is not always reliable for filenames, abbreviations, numbers, proper nouns, or exact phrases. Pure BM25 can miss a useful paraphrase. Mneme keeps both retrieval signals.</p><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>User question</span></span>
<span class="line"><span>  → query decomposition</span></span>
<span class="line"><span>  → concurrent hybrid retrieval / Graph RAG expansion</span></span>
<span class="line"><span>  → chunk deduplication and dynamic Top-K</span></span>
<span class="line"><span>  → PDF anchor enrichment</span></span>
<span class="line"><span>  → cited, bounded untrusted-document context</span></span>
<span class="line"><span>  → LLM answer + verifiable sources</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h2><h3 id="semantic-search" tabindex="-1">Semantic Search <a class="header-anchor" href="#semantic-search" aria-label="Permalink to &quot;Semantic Search&quot;">​</a></h3><ul><li><strong>Sentence Transformers</strong> produce embeddings</li><li><strong>ChromaDB</strong> provides semantic retrieval with cosine similarity</li><li>Default model: <code>all-MiniLM-L6-v2</code> (auto-downloaded from ModelScope if not cached)</li></ul><h3 id="lexical-search" tabindex="-1">Lexical Search <a class="header-anchor" href="#lexical-search" aria-label="Permalink to &quot;Lexical Search&quot;">​</a></h3><ul><li><strong>BM25</strong> provides keyword-based retrieval</li><li>Custom tokenization supports bilingual text, case folding, and punctuation stripping</li><li>Incremental BM25 tokenization reuse for unchanged chunks on index updates</li></ul><h3 id="rrf-fusion" tabindex="-1">RRF Fusion <a class="header-anchor" href="#rrf-fusion" aria-label="Permalink to &quot;RRF Fusion&quot;">​</a></h3><p>RRF (Reciprocal Rank Fusion) combines the ranked lists instead of comparing incompatible raw scores:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RRF score = Σ 1 / (k + rank)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>RRF is simple and explainable. It does not require semantic distances and BM25 scores to share the same scale.</p><h3 id="dynamic-top-k" tabindex="-1">Dynamic Top-K <a class="header-anchor" href="#dynamic-top-k" aria-label="Permalink to &quot;Dynamic Top-K&quot;">​</a></h3><p>After fusion, Mneme selects a dynamic Top-K from score gaps:</p><ul><li>A clear gap becomes a natural cutoff</li><li>Configured lower (<code>LLM_TOP_K_MIN</code>) and upper (<code>LLM_TOP_K_MAX</code>) bounds still apply when the gap is not decisive</li></ul><h2 id="retrieval-quality" tabindex="-1">Retrieval Quality <a class="header-anchor" href="#retrieval-quality" aria-label="Permalink to &quot;Retrieval Quality&quot;">​</a></h2><p>This design leaves retrieval quality measurable. Recall@k, MRR, and nDCG can be used as regression signals instead of relying on the impression that an answer &quot;feels better.&quot; The repository includes benchmark data and quality-gate helpers under <code>benchmarks/</code>.</p><h2 id="best-for" tabindex="-1">Best For <a class="header-anchor" href="#best-for" aria-label="Permalink to &quot;Best For&quot;">​</a></h2><p>Standard RAG (hybrid retrieval) is best for general Q&amp;A and broad document sets. For connected or cross-document questions, use <a href="/MNEME/features/graph-rag">Graph RAG</a>.</p>`,20)])])}const b=a(i,[["render",t]]);export{h as __pageData,b as default};
